// @ts-check
import { fileURLToPath } from 'node:url';
import { defineConfig } from 'astro/config';
import sitemap from '@astrojs/sitemap';
import { lastModified } from './scripts/lastmod.mjs';
import { llmsFull } from './scripts/llms-full.mjs';

/**
 * The public origin. Every absolute URL (canonical, og:url, sitemap,
 * robots.txt, llms.txt, JSON-LD) derives from this one value.
 */
const SITE_URL = process.env.SITE_URL || 'https://pacer.andrechek.com';

// The README screenshots, regenerated by CI on every release-bound PR
// (docs/screenshots.md), are the site's screenshots too: imported from the
// repo, never copied, so the site can't fall behind the app.
const screenshots = fileURLToPath(new URL('../docs/screenshots', import.meta.url));

export default defineConfig({
  site: SITE_URL,
  output: 'static',
  trailingSlash: 'always',
  build: { inlineStylesheets: 'always' },
  // Astro's compression drops the line break between text and an inline element
  // wrapped onto the next source line ("stats to<a>PostHog"), gluing words together.
  compressHTML: false,
  integrations: [
    sitemap({
      filter: (page) => !/\/404\/?$/.test(page),
      // <lastmod>: when the page's source last changed in git (scripts/lastmod.mjs).
      serialize: (item) => ({
        ...item,
        lastmod: lastModified(new URL(item.url).pathname).toISOString(),
      }),
    }),
    llmsFull(),
  ],
  vite: {
    resolve: { alias: { '@screenshots': screenshots } },
    // The screenshots and release notes live outside site/.
    server: { fs: { allow: ['..'] } },
  },
});
